import{_ as r,H as t,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"再次出发｜通向高手之路","description":"","frontmatter":{},"headers":[],"relativePath":"10x程序员工作法/再次出发｜通向高手之路.md","filePath":"10x程序员工作法/再次出发｜通向高手之路.md","lastUpdated":1779815258000}'),o={name:"10x程序员工作法/再次出发｜通向高手之路.md"};function l(i,e,p,_,g,s){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="再次出发-通向高手之路" tabindex="-1">再次出发｜通向高手之路 <a class="header-anchor" href="#再次出发-通向高手之路" aria-label="Permalink to &quot;再次出发｜通向高手之路&quot;">​</a></h1><p>你好，我是郑晔！</p><p>时间好快，《 <a href="https://time.geekbang.org/column/intro/100022301" target="_blank" rel="noreferrer">10x 程序员工作法</a>》上线已经有 6 年多了，这个专栏是我多年工作经验一次相对完整的总结。6 年时间，我也经历不少变动，但其实，我也没有离开大家。这期间，我在《极客时间》上又写了几个专栏：</p><ul><li>《 <a href="https://time.geekbang.org/column/intro/100052601" target="_blank" rel="noreferrer">软件设计之美</a>》讲述了如何进行软件设计。</li><li>《 <a href="https://time.geekbang.org/column/intro/100068401" target="_blank" rel="noreferrer">代码之丑</a>》讨论了应该如何编写代码。</li><li>《 <a href="https://time.geekbang.org/column/intro/100085101" target="_blank" rel="noreferrer">程序员的测试课</a>》总结了程序员应该如何写测试。</li><li>《 <a href="https://time.geekbang.org/column/intro/100839101" target="_blank" rel="noreferrer">程序员的 AI 开发第一课</a>》介绍了 AI 应用开发要如何入门。</li></ul><p>除了专栏，我还在极客时间做过几次分享，期间谈到最多的一个主题就是程序员如何精进。</p><p>从 2022 年底 ChatGPT 问世之后，我看到了整个行业正在发生剧烈的变化。一方面，如何将 AI 能力应用到业务中，这是全行业的人都在努力寻找答案的问题，另一方面，程序员这个职业也在被 AI 逐步改变，越来越多的程序员在工作中用起了 AI。</p><p>2023 年初，我还专门加餐过一次，那时 Github Copilot 刚刚问世，AI 辅助开发小荷才露尖尖角，而站在 2025 年初看，Cursor、Cline 等工具已经让 Github Copilot 类的工具显得不够看了。</p><p>作为一个不断思考精进的程序员，我也需要回答一个问题：自己曾以为正确的很多内容是否需要修正。</p><p>幸运的是，至少从目前来看，《 <a href="https://time.geekbang.org/column/intro/100022301" target="_blank" rel="noreferrer">10x 程序员工作法</a>》的大部分内容并不会因为 AI 的流行而改变。AI 可以帮助我们提高工作效率，但它并不能替代一个会工作的人。所以，成为一个更好的程序员，依然值得我们追求。在很多人的心中，更好的程序员有一个代名词：高手。</p><p>对于大部分程序员来说，无论在真实工作中他的职务是什么，在他内心里，都更希望成为一个高手，一个能够不断精进的高手，但如何达成这个目标却是让很多人困惑的事。</p><p>接下来一段时间，我会开启《 <a href="https://time.geekbang.org/column/intro/100022301" target="_blank" rel="noreferrer">10x 程序员工作法</a>》的加餐，其主题就是“通向高手之路”。我会把我这几年的思考以及学到的一些新知做一个整合，探讨如何不断提升自己，做一个更好的 10x 程序员。</p><p>欢迎各位新老同学回来，我们一起前行，成为高手！</p>',12)])])}const m=r(o,[["render",l]]);export{h as __pageData,m as default};
